sed -i '143,160d' pygments/lexers/jvm.py
sed -i '143i\
    def get_tokens_unprocessed(self, text):
        for index, token, value in JavaLexer.get_tokens_unprocessed(self, text):
            if token is Name and value in self.aj_keywords:
                yield index, Keyword, value
            elif token is Name.Label and value in self.aj_inter_type:
                yield index, Keyword, value[:-1]
                yield index, Operator, value[-1]
            elif token is Name.Decorator and value in self.aj_inter_type_annotation:
                yield index, Keyword, value
            elif token is Name.Decorator and value == '''@declare''':
                yield index, Keyword, value
            elif token is Name and value in {'''parents''', '''warning''', '''error''', '''soft''', '''precedence'''}:
                # Check if the next character is a colon for inter-type declarations
                next_char_index = index + len(value)
                if next_char_index < len(text) and text[next_char_index] == ''':''':
                    yield index, Keyword, value
            else:
                yield index, token, value' pygments/lexers/jvm.py
